// Eingabe der Runtime: { to, subject, body, cc?, in_reply_to? }
const incoming = $input.first().json;
const inp = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
if (typeof inp.to !== 'string' || inp.to.trim() === '') throw new Error('mail-draft: Feld "to" fehlt');
if (typeof inp.body !== 'string' || inp.body.trim() === '') throw new Error('mail-draft: Feld "body" fehlt');
return [{ json: {
  to: inp.to.trim(),
  cc: typeof inp.cc === 'string' ? inp.cc.trim() : '',
  subject: typeof inp.subject === 'string' ? inp.subject : '',
  message: inp.body,
  in_reply_to: typeof inp.in_reply_to === 'string' ? inp.in_reply_to.trim() : ''
} }];

const m = $input.first().json || {};
return [{ json: {
  draft_id: String(m.id || m.draftId || m.message?.id || ''),
  mailbox: 'Drafts',
  created: true,
  sent: false
} }];
